"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
export default function PetitionList() {
  const [petitions, setPetitions] = useState<any[]>([]);
  const [location, setLocation] = useState("");
  const [category, setCategory] = useState("");
  const [status, setStatus] = useState("");

  useEffect(() => {
    fetchPetitions();
  }, [location, category, status]);

  const fetchPetitions = async () => {
    const baseUrl = "http://127.0.0.1:5000/api/petitions";

    const params = new URLSearchParams();

    if (location) params.append("location", location);
    if (category) params.append("category", category);
    if (status) params.append("status", status);

    const query = params.toString()
      ? `${baseUrl}?${params.toString()}`
      : baseUrl;

    const res = await fetch(query, { cache: "no-store" });
    const data = await res.json();
    setPetitions(data);
  };

  return (
  <div className="min-h-screen bg-slate-900 text-white p-10">
    <h1 className="text-3xl font-bold mb-6">Explore Petitions</h1>

    {/* Filter Section */}
    <div className="flex gap-4 mb-6">
      <select
        onChange={(e) => setLocation(e.target.value)}
        className="border border-slate-600 bg-slate-800 text-white p-2 rounded-lg"
      >
        <option value="">All Locations</option>
        <option value="Chennai">Chennai</option>
        <option value="Bangalore">Bangalore</option>
        <option value="Hyderabad">Hyderabad</option>
        <option value="Mumbai">Mumbai</option>
        <option value="Delhi">Delhi</option>
        <option value="Kolkata">Kolkata</option>
        <option value="Pune">Pune</option>
        <option value="Coimbatore">Coimbatore</option>
        <option value="Madurai">Madurai</option>
        <option value="Ahmedabad">Ahmedabad</option>
      </select>

      <select
        onChange={(e) => setCategory(e.target.value)}
        className="border border-slate-600 bg-slate-800 text-white p-2 rounded-lg"
      >
        <option value="">All Categories</option>
        <option value="Environment">Environment</option>
      </select>

      <select
        onChange={(e) => setStatus(e.target.value)}
        className="border border-slate-600 bg-slate-800 text-white p-2 rounded-lg"
      >
        <option value="">All Status</option>
        <option value="active">Active</option>
        <option value="under review">Under Review</option>
        <option value="closed">Closed</option>
      </select>
    </div>

    <p className="mb-4">
      Total petitions: {petitions.length}
    </p>

    {/* Petition Cards */}
    <div className="grid gap-4">
      {petitions.map((petition) => (
        <Link key={petition._id} href={`/petitions/${petition._id}`}>
          <div className="p-6 bg-slate-800 text-white shadow-xl rounded-xl border border-slate-700 hover:scale-105 transition cursor-pointer">
            <h2 className="text-xl font-semibold">
              {petition.title}
            </h2>

            <p className="text-slate-300">
              {petition.category}
            </p>

            <p className="text-slate-300">
              {petition.location}
            </p>

            <p className="mt-2 font-medium">
              Status: {petition.status}
            </p>
          </div>
        </Link>
      ))}
    </div>
  </div>
);
}